        // Datetimes don't have a single obvious numeric representation, and if we chose one it would be ambiguous to the user

        let year_three = chrono::NaiveDate::from_ymd_opt(3, 1, 1)
            .unwrap()
            .and_hms_opt(0, 0, 0)
            .unwrap()
            .and_utc();

