            Value::test_int(10),
            Value::test_float(6.0),
            Value::test_int(1),
            Value::test_binary([3]),
            Value::test_string("2"),
            Value::test_date(year_three.into()),
            Value::test_int(4),
            Value::test_binary([52]),
            Value::test_float(9.0),
            Value::test_string("5"),
            Value::test_date(chrono::DateTime::UNIX_EPOCH.into()),
            Value::test_int(7),
            Value::test_string("8"),
            Value::test_float(3.0),
            Value::test_string("foobar"),
        ];
        assert!(sort(&mut list, false, true).is_ok());
        assert_eq!(
            list,
            vec![
                Value::test_int(1),
                Value::test_string("2"),
                Value::test_float(3.0),
                Value::test_int(4),
                Value::test_string("5"),
                Value::test_float(6.0),
                Value::test_int(7),
                Value::test_string("8"),
                Value::test_float(9.0),
                Value::test_int(10),
                Value::test_string("foobar"),
