pub fn overview_page(sniffer: &Sniffer) -> Container<'_, Message, StyleType> {
    let Settings { language, .. } = sniffer.conf.settings;

    let mut body = Column::new();
    let mut tab_and_body = Column::new().height(Length::Fill);

