    pub fn map<U: ?Sized, T, F, FMut>(
        self,
        map: F,
        map_mut: FMut,
    ) -> SelectorScope<MappedMutSignal<U, Lens, F, FMut>>
    where
        F: Fn(&T) -> &U,
        FMut: Fn(&mut T) -> &mut U,
    {
        self.map_writer(move |write| MappedMutSignal::new(write, map, map_mut))
