impl Function {
  pub(crate) fn argc(&self) -> RangeInclusive<usize> {
    match *self {
      Nullary(_) => 0..=0,
      Unary(_) => 1..=1,
      UnaryOpt(_) => 1..=2,
      UnaryPlus(_) => 1..=usize::MAX,
      Binary(_) => 2..=2,
      BinaryPlus(_) => 2..=usize::MAX,
      Ternary(_) => 3..=3,
    }
  }
}

fn absolute_path(context: Context, path: &str) -> FunctionResult {
  let abs_path_unchecked = context
    .execution_context
    .working_directory()
    .join(path)
    .lexiclean();
