                (Some(0x1b), Some(b'O'), Some(final_byte), _) if raw_bytes.len() == 3 => {
                    format!("\x1b[1;{}{}", modifier_code, final_byte as char).into_bytes()
                },
                _ => raw_bytes,
            }
        } else {
            raw_bytes
        };

        Some((
            KeyWithModifier::new_with_modifiers(bare_key, modifiers),
            raw_bytes,
        ))
    }
}

